const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const antRegion = ee.Geometry.Polygon(
      [[[-180, -60], [-180, -90], [180, -90], [180, -60], [-180, -60]]],
      null,
      false
    );
    const scale = 10000; // meters
    const dates = [
      { key: 'Jan1', label: '2021-01-01' },
      { key: 'Oct7', label: '2021-10-07' }
    ];
    const DU_to_mol_per_m2 = 2.1415e-5;
    const thresholdMol = 220 * DU_to_mol_per_m2;

    // Region area in m2 for reference
    const regionAreaM2 = await ee.Image.pixelArea()
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: antRegion,
        scale: scale,
        maxPixels: 1e9
      })
      .get('area')
      .getInfo();

    console.log(`Region: Antarctica south of 60S; Area: ${(regionAreaM2 / 1e12).toFixed(3)} Mkm2; Threshold: 220 DU`);

    async function getCompositeForDate(dateStr) {
      const sources = [
        { id: 'COPERNICUS/S5P/OFFL/L3_O3_TCL', winDays: 1, tag: 'OFFL' },
        { id: 'COPERNICUS/S5P/NRTI/L3_O3_TCL', winDays: 1, tag: 'NRTI' },
        { id: 'COPERNICUS/S5P/OFFL/L3_O3_TCL', winDays: 3, tag: 'OFFL3d' },
        { id: 'COPERNICUS/S5P/NRTI/L3_O3_TCL', winDays: 3, tag: 'NRTI3d' }
      ];
      for (let s of sources) {
        const start = ee.Date(dateStr).advance(-(Math.floor(s.winDays / 2)), 'day');
        const end = ee.Date(dateStr).advance(Math.ceil(s.winDays / 2), 'day');
        const col = ee.ImageCollection(s.id)
          .filterDate(s.winDays === 1 ? ee.Date(dateStr) : start, s.winDays === 1 ? ee.Date(dateStr).advance(1, 'day') : end)
          .filterBounds(antRegion);
        const size = await col.size().getInfo();
        if (size > 0) {
          // Build composite
          const img = col.select(['O3_column_number_density', 'qa_value']).mean();
          const qaMask = img.select('qa_value').gt(0.5);
          const ozone = img.select('O3_column_number_density').updateMask(qaMask);
          return { ozone, size, source: s.tag, winDays: s.winDays };
        }
      }
      return { ozone: null, size: 0, source: 'none', winDays: 0 };
    }

    async function summarize(dateStr, label) {
      const comp = await getCompositeForDate(dateStr);
      if (!comp.ozone) {
        console.log(`${label} Images: 0 src:none`);
        return { status: 'C1' };
      }
      // Valid pixel count
      const count = await comp.ozone.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: antRegion,
        scale: scale,
        maxPixels: 1e9
      }).get('O3_column_number_density').getInfo();
      console.log(`${label} Images: ${comp.size} src:${comp.source} win:${comp.winDays}d`);
      if (!count || count === 0) {
        console.log(`${label} Valid px: 0`);
        return { status: 'C2' };
      }
      // Areas
      const areaImg = ee.Image.pixelArea();
      const validAreaM2 = await areaImg.updateMask(comp.ozone.mask())
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: antRegion,
          scale: scale,
          maxPixels: 1e9
        }).get('area').getInfo();
      const holeMask = comp.ozone.lt(thresholdMol);
      const holeAreaM2 = await areaImg.updateMask(comp.ozone.mask().and(holeMask))
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: antRegion,
          scale: scale,
          maxPixels: 1e9
        }).get('area').getInfo();

      // Validate numbers
      if (holeAreaM2 == null || validAreaM2 == null || isNaN(holeAreaM2) || isNaN(validAreaM2) || holeAreaM2 < 0 || validAreaM2 <= 0) {
        console.log(`${label} Calculation invalid.`);
        return { status: 'C3' };
      }

      console.log(`${label} Valid px: ${count}, Valid area: ${(validAreaM2 / 1e12).toFixed(3)} Mkm2 (${(100 * validAreaM2 / regionAreaM2).toFixed(1)}%)`);
      console.log(`${label} O3<220DU area: ${(holeAreaM2 / 1e12).toFixed(3)} Mkm2 (${(100 * holeAreaM2 / validAreaM2).toFixed(1)}%)`);
      return { status: 'OK', holeAreaM2, validAreaM2, comp };
    }

    const jan = await summarize('2021-01-01', 'Jan1');
    if (jan.status !== 'OK') {
      console.log(jan.status);
      return;
    }
    const oct = await summarize('2021-10-07', 'Oct7');
    if (oct.status !== 'OK') {
      console.log(oct.status);
      return;
    }

    console.log(`Compare Hole Area (Mkm2): Oct7=${(oct.holeAreaM2 / 1e12).toFixed(3)} vs Jan1=${(jan.holeAreaM2 / 1e12).toFixed(3)}`);
    const answer = (oct.holeAreaM2 > jan.holeAreaM2) ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
